<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,http,image,type Shop,type Note,type Voucher,type User} from './api'
import {useSession} from './session'
import Card from './Card.vue'
const route=useRoute(),router=useRouter(),session=useSession()
const loading=ref(false),error=ref(''),shops=ref<Shop[]>([]),notes=ref<Note[]>([]),types=ref<{id:number;name:string}[]>([]),shop=ref<Shop|null>(null),note=ref<Note|null>(null),vouchers=ref<Voucher[]>([]),query=ref(''),type=ref(0),page=ref(1),hasMore=ref(false),near=ref(false),coords=ref<{x:number;y:number}|null>(null),signCount=ref(0),followed=ref(false),working=ref(false),orderText=ref(''),lastId=ref(Date.now()),offset=ref(0),title=ref(''),content=ref(''),shopId=ref(1),photo=ref<File|null>(null),now=ref(Date.now())
let generation=0;const clock=setInterval(()=>now.value=Date.now(),1000);onUnmounted(()=>clearInterval(clock))
const field=(v:Voucher,k:'beginTime'|'endTime')=>v[k]?new Date(v[k]!).getTime():0
function couponState(v:Voucher){if(v.status!==1)return '已下架';if(field(v,'beginTime')>now.value)return '尚未开始';if(field(v,'endTime')&&field(v,'endTime')<now.value)return '已结束';if(v.stock!==undefined&&v.stock<=0)return '已售罄';return v.type===1?'立即秒杀':'到店咨询'}
function timeLeft(v:Voucher){const end=field(v,'beginTime')>now.value?field(v,'beginTime'):field(v,'endTime');if(!end||end<now.value)return '';const s=Math.floor((end-now.value)/1000);return `${Math.floor(s/86400)}天 ${String(Math.floor(s/3600)%24).padStart(2,'0')}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
async function load(append=false){const id=++generation;loading.value=true;error.value='';if(!append){page.value=1;lastId.value=Date.now();offset.value=0;notes.value=[];shops.value=[];shop.value=null;note.value=null;orderText.value=''}try{
 const path=route.path
 if(path==='/'||path==='/shops'){
 types.value=await api('/shop-type/list');if(!type.value&&types.value.length)type.value=types.value[0].id
 const q=route.query.q?.toString()||query.value;query.value=q
 const url=q?'/shop/of/name?name='+encodeURIComponent(q):`/shop/of/type?typeId=${type.value}`
 const geo=near.value&&coords.value&&!q?`&x=${coords.value.x}&y=${coords.value.y}`:''
 const data=await api<Shop[]>(url+`&current=${page.value}`+geo)||[];if(id!==generation)return;shops.value=append?[...shops.value,...data]:data;hasMore.value=data.length===5
 if(path==='/')notes.value=await api<Note[]>('/blog/hot')||[]
 }else if(path.startsWith('/shop/')){shop.value=await api<Shop>('/shop/'+route.params.id);vouchers.value=await api<Voucher[]>('/voucher/list/'+route.params.id)||[];notes.value=await api<Note[]>('/blog/hot?shopId='+route.params.id)||[]
 }else if(path.startsWith('/note/')){note.value=await api<Note>('/blog/'+route.params.id);if(session.user&&note.value.userId!==session.user.id)followed.value=await api<boolean>('/follow/or/not/'+note.value.userId)
 }else if(path==='/notes'||path==='/me'){
 if(path==='/me'&&!session.requireLogin())return
 const url=path==='/me'?'/blog/of/me':route.query.user?'/blog/of/user?id='+route.query.user:'/blog/hot'
 const data=await api<Note[]>(url+(url.includes('?')?'&':'?')+'current='+page.value)||[];notes.value=append?[...notes.value,...data]:data;hasMore.value=data.length===(path==='/notes'&&!route.query.user?5:10)
 if(path==='/me')signCount.value=await api<number>('/user/sign/count')
 }else if(path==='/feed'){if(!session.requireLogin())return;const data=await api<{list:Note[];minTime:number;offset:number}|null>(`/blog/of/follow?lastId=${lastId.value}&offset=${offset.value}`);notes.value=append?[...notes.value,...(data?.list||[])]:data?.list||[];hasMore.value=(data?.list?.length||0)===5;if(data){offset.value=data.minTime===lastId.value?offset.value+data.offset:data.offset;lastId.value=data.minTime}}
 else if(path==='/write'){shopId.value=Number(route.query.shop)||1;session.requireLogin()}
 }catch(e:any){if(id===generation)error.value=e.message}finally{if(id===generation)loading.value=false}}
watch(()=>[route.fullPath,session.user?.id],()=>load(),{immediate:true})
async function more(){page.value++;await load(true)}
function search(){router.push({path:'/shops',query:query.value.trim()?{q:query.value.trim()}:{}});if(route.path==='/shops')load()}
async function filter(id:number){type.value=id;query.value='';await router.replace('/shops');load()}
async function locate(){if(!navigator.geolocation)return session.toast('当前浏览器不支持定位');working.value=true;navigator.geolocation.getCurrentPosition(p=>{coords.value={x:p.coords.longitude,y:p.coords.latitude};near.value=true;query.value='';router.replace('/shops').then(()=>load());working.value=false},()=>{session.toast('无法获取位置，请允许浏览器定位，或填写经纬度');working.value=false},{timeout:10000})}
async function manualLocation(){if(!coords.value||!Number.isFinite(coords.value.x)||!Number.isFinite(coords.value.y)||Math.abs(coords.value.x)>180||Math.abs(coords.value.y)>90)return session.toast('请输入有效经纬度');near.value=true;query.value='';await router.replace('/shops');load()}
async function like(n:Note){if(!session.requireLogin()||working.value)return;working.value=true;try{await api('/blog/like/'+n.id,'PUT');n.liked+=n.isLike?-1:1;n.isLike=!n.isLike}catch(e:any){session.toast(e.message)}finally{working.value=false}}
async function follow(){if(!session.requireLogin()||!note.value)return;working.value=true;try{await api(`/follow/${note.value.userId}/${!followed.value}`,'PUT');followed.value=!followed.value;session.toast(followed.value?'已关注，之后的新笔记会出现在关注动态':'已取消关注')}catch(e:any){session.toast(e.message)}finally{working.value=false}}
async function sign(){working.value=true;try{await api('/user/sign','POST');signCount.value=await api('/user/sign/count');session.toast('今日签到成功')}catch(e:any){session.toast(e.message)}finally{working.value=false}}
async function seckill(v:Voucher){if(!session.requireLogin())return;working.value=true;orderText.value='';try{const id=await api<string>('/voucher-order/seckill/'+v.id,'POST');orderText.value='已受理，订单号：'+id+'。后台正在处理订单。';for(let attempt=0;attempt<10;attempt++){await new Promise(resolve=>setTimeout(resolve,1000));const result=await api<{status:string}>('/voucher-order/status/'+id);if(result.status==='confirmed'){orderText.value='秒杀成功！订单号：'+id;break}}vouchers.value=await api('/voucher/list/'+route.params.id)}catch(e:any){session.toast(e.message)}finally{working.value=false}}
async function publish(){if(!session.requireLogin())return;working.value=true;try{let images='';if(photo.value){if(photo.value.size>5*1024*1024)throw new Error('照片不能超过 5MB');if(!['image/jpeg','image/png','image/webp'].includes(photo.value.type))throw new Error('请选择 JPG、PNG 或 WebP 图片');const form=new FormData();form.append('file',photo.value);const r=await http.post('/upload/blog',form);if(!r.data.success)throw new Error('图片上传失败');images=r.data.data}const id=await api<number>('/blog','POST',{shopId:shopId.value,title:title.value,content:content.value,images});session.toast('笔记发布成功');router.push('/note/'+id)}catch(e:any){session.toast(e.message)}finally{working.value=false}}
</script>
<template>
<section v-if="route.path==='/'" class="hero"><div><p class="eyebrow">EXPLORE THE EVERYDAY / 城市生活指南</p><h1>好生活，<br>藏在街头巷尾。</h1><p>寻找一间小店，记录一次心动。<br>和有趣的人，一起重新认识这座城市。</p><form class="search" @submit.prevent="search"><input v-model="query" aria-label="搜索商户" placeholder="今天想去哪？搜索商户名称"><button>探索好店 ↗</button></form></div><div class="hero-art" role="img" aria-label="城市街巷的抽象插画"></div></section>
<div v-if="error" class="notice error" role="alert">{{error}} <button class="secondary" @click="load()">重试</button></div>
<template v-if="route.path==='/'||route.path==='/shops'">
<div v-if="route.path==='/shops'" class="page-title"><p class="eyebrow">FIND YOUR NEXT FAVORITE</p><h1>城市好店指南</h1><form class="search" @submit.prevent="search"><input v-model="query" placeholder="搜索商户名称" aria-label="搜索商户"><button>搜索</button><button type="button" class="secondary" :disabled="working" @click="locate">◎ 附近商户</button></form><details><summary>手动设置位置（可用样例：120.149192, 30.316078）</summary><form class="row" @submit.prevent="manualLocation"><label>经度<input type="number" step="any" :value="coords?.x" @input="coords={x:Number(($event.target as HTMLInputElement).value),y:coords?.y||0}"></label><label>纬度<input type="number" step="any" :value="coords?.y" @input="coords={x:coords?.x||0,y:Number(($event.target as HTMLInputElement).value)}"></label><button>查找附近</button></form></details></div>
<div class="chips"><button v-for="(t,i) in types" :key="t.id" class="chip" :class="{active:type===t.id&&!query}" @click="filter(t.id)">{{['◈','☕','✦','♧'][i%4]}} {{t.name}}</button></div><div class="section-head"><div><p class="eyebrow">CURATED LOCAL FINDS</p><h2>{{query?'搜索结果':near?'附近 5 公里':'值得一逛的好店'}}</h2></div><RouterLink v-if="route.path==='/'" to="/shops" class="muted">全部商户 ↗</RouterLink><button v-if="near" class="secondary" @click="near=false;load()">取消附近筛选</button></div><div class="grid"><Card v-for="s in shops" :key="s.id" :shop="s"/><p v-if="!loading&&!shops.length" class="empty">暂无匹配商户，试试其他分类、关键词或位置。</p></div><button v-if="route.path==='/shops'&&hasMore" class="full secondary" :disabled="loading" @click="more">加载更多商户</button>
</template>
<template v-if="route.path.startsWith('/shop/')&&shop"><div class="page-title"><RouterLink to="/shops" class="muted">← 返回商户列表</RouterLink></div><div class="detail"><section class="panel"><div class="cover"><img v-if="image(shop.images)" :src="image(shop.images)" alt="商户图片"><span v-else>☕</span></div><h1 class="detail-title">{{shop.name}}</h1><p><span class="rating">★ {{(shop.score/10).toFixed(1)}}</span> · 已售 {{shop.sold}} <span v-if="shop.avgPrice"> · 人均 ¥{{shop.avgPrice}}</span></p><p>地址 · {{shop.address}}</p><p>营业时间 · {{shop.openHours||'请联系商户确认'}}</p><RouterLink class="button secondary" :to="'/write?shop='+shop.id" @click="shopId=shop.id">写探店笔记 ↗</RouterLink></section><aside><h2>店铺优惠</h2><p class="muted">遇见好店，也遇见好价格</p><article v-for="v in vouchers" :key="v.id" class="coupon"><span class="tag">{{v.type===1?'限时秒杀':'商户优惠'}}</span><h3>{{v.title}}</h3><p class="muted">{{v.subTitle}}</p><p><span class="price">¥{{(v.payValue/100).toFixed(2)}}</span> <small>抵 ¥{{(v.actualValue/100).toFixed(2)}}</small></p><p v-if="v.stock!==undefined" class="muted">数据库剩余库存 {{v.stock}} · 以实际下单为准</p><p class="muted">{{timeLeft(v)}}</p><button class="full" :disabled="working||couponState(v)!=='立即秒杀'" @click="seckill(v)">{{couponState(v)}}</button></article><p v-if="!vouchers.length" class="empty">这家店暂未发布优惠券</p><p v-if="orderText" class="notice" role="status">{{orderText}}</p></aside></div><div class="section-head"><h2>这家店的探店笔记</h2></div><div class="grid"><Card v-for="n in notes" :key="n.id" :note="n" @like="like"/><p v-if="!notes.length" class="empty">还没有探店笔记，来分享你的体验吧。</p></div></template>
<template v-if="route.path==='/me'"><div v-if="session.user" class="panel profile"><div class="avatar">{{session.user.nickName?.slice(0,1)||'遇'}}</div><div><p class="eyebrow">MY CITY JOURNAL</p><h2>{{session.user.nickName}}</h2><span class="muted">连续签到 {{signCount}} 天</span></div><button :disabled="working" @click="sign">今日签到</button><button class="secondary" @click="session.logout()">退出登录</button></div><p v-else class="empty"><button @click="session.loginOpen=true">登录后查看个人中心</button></p></template>
<template v-if="route.path==='/'||['/notes','/feed','/me'].includes(route.path)"><div class="section-head"><div><p class="eyebrow">STORIES FROM THE NEIGHBORHOOD</p><h2>{{route.path==='/feed'?'关注的人，最近在逛什么':route.path==='/me'?'我的探店笔记':route.query.user?'TA 的探店笔记':'街巷里的新发现'}}</h2></div><RouterLink class="button secondary" to="/write">＋ 写笔记</RouterLink></div><div class="grid"><Card v-for="n in notes" :key="n.id" :note="n" @like="like"/><div v-if="!loading&&!notes.length" class="empty">{{route.path==='/feed'?'还没有动态。关注笔记作者后，TA 新发布的笔记会出现在这里。':'还没有笔记，来记录第一次探店吧。'}}<button v-if="!session.user&&route.path==='/feed'" @click="session.loginOpen=true">先登录</button></div></div><button v-if="hasMore&&route.path!=='/'" class="full secondary" :disabled="loading" @click="more">加载更多笔记</button></template>
<template v-if="route.path.startsWith('/note/')&&note"><RouterLink to="/notes" class="muted">← 返回探店笔记</RouterLink><article class="panel reading"><p class="eyebrow">CITY STORIES / 探店手记</p><h1 class="detail-title">{{note.title}}</h1><div class="row between"><RouterLink :to="'/notes?user='+note.userId">{{note.name}} · {{new Date(note.createTime).toLocaleDateString()}}</RouterLink><button v-if="session.user?.id!==note.userId" class="secondary" :disabled="working" @click="follow">{{followed?'已关注':'＋ 关注作者'}}</button></div><img v-if="image(note.images)" class="note-image" :src="image(note.images)" alt="探店照片"><p class="content">{{note.content}}</p><div class="row between"><RouterLink class="button secondary" :to="'/shop/'+note.shopId">去看看这家店 ↗</RouterLink><button :disabled="working" @click="like(note)">{{note.isLike?'♥ 已点赞':'♡ 点赞'}} {{note.liked}}</button></div></article></template>
<section v-if="route.path==='/write'" class="panel reading"><p class="eyebrow">SHARE YOUR LITTLE DISCOVERY</p><h1 class="detail-title">把好去处，写成故事。</h1><form @submit.prevent="publish"><label for="shop-id">商户 ID（在商户详情中进入可自动填写）</label><input id="shop-id" v-model="shopId" type="number" min="1" required><label for="note-title">笔记标题</label><input id="note-title" v-model="title" maxlength="100" required placeholder="一句话说说这次发现"><label for="note-content">探店体验</label><textarea id="note-content" v-model="content" maxlength="2000" required placeholder="环境、味道、服务，有哪些值得分享的小细节？"></textarea><label for="photo">上传照片（可选）</label><input id="photo" type="file" accept="image/jpeg,image/png,image/webp" @change="photo=($event.target as HTMLInputElement).files?.[0]||null"><button class="full" :disabled="working">{{working?'发布中…':'发布探店笔记'}}</button></form></section><p v-if="loading" class="loading" role="status">正在发现街巷里的好去处…</p>
</template>
